insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('la-experiencia-de-llegar-a-un-lugar-nuevo-desafios-de-adaptacion','sociedad',array['educacion']::text[],'La experiencia de llegar a un lugar nuevo: desafíos de adaptación y dificultades para construir nuevas relaciones','Recoge, con respeto y de forma voluntaria, qué desafíos enfrentan las personas que llegan a una ciudad o una comunidad nueva, desde encontrar vivienda hasta hacer amistades, y qué las ayudó a adaptarse.','Investigación','4 semanas',26,array['Adaptación','Migración interna']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion entrevistas. analisis cualitativo. empatia. redaccion. un formulario en linea. una guia de conversacion. un editor de documentos.',$a37sld${"id": "la-experiencia-de-llegar-a-un-lugar-nuevo-desafios-de-adaptacion", "area": "sociedad", "areas2": ["educacion"], "titulo": "La experiencia de llegar a un lugar nuevo: desafíos de adaptación y dificultades para construir nuevas relaciones", "resumen": "Recoge, con respeto y de forma voluntaria, qué desafíos enfrentan las personas que llegan a una ciudad o una comunidad nueva, desde encontrar vivienda hasta hacer amistades, y qué las ayudó a adaptarse.", "tipo": "Investigación", "tiempo": "4 semanas", "horas": 26, "etiquetas": ["Adaptación", "Migración interna"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Mudarse a otra ciudad, a una residencia estudiantil o a un barrio nuevo implica adaptarse a costumbres, climas, costos y a no tener las redes de siempre. Muchas personas lo viven en silencio, pensando que son las únicas.", "Documentar estas experiencias ayuda a que los recién llegados se sientan acompañados y a que las comunidades se preparen para recibirlos."], "desarrollar": ["Con una encuesta anónima y cinco a diez conversaciones voluntarias con personas que llegaron a un lugar nuevo, pregunta qué fue lo más difícil, qué las ayudó y qué les hubiera gustado saber antes.", "Agrupa las respuestas por temas, como vivienda, costos, clima, trato y amistades, y resume los hallazgos en una guía de recomendaciones cortas con testimonios anónimos."], "ampliaciones": [{"titulo": "Primer mes", "aporta": "organiza los desafíos según el tiempo de llegada."}, {"titulo": "Quienes reciben", "aporta": "recoge también la perspectiva de la comunidad que recibe."}, {"titulo": "Mapa de apoyos", "aporta": "lista los apoyos disponibles para recién llegados."}], "objetivos": ["Recoger experiencias de adaptación.", "Agrupar desafíos.", "Identificar apoyos útiles.", "Redactar recomendaciones."], "habilidades": ["Entrevistas.", "Análisis cualitativo.", "Empatía.", "Redacción."], "herramientas": ["Un formulario en línea.", "Una guía de conversación.", "Un editor de documentos."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Trata el tema con respeto: usa casos inventados o anónimos, sin datos que identifiquen a nadie, y si alguien necesita ayuda urgente remítelo a los servicios oficiales de atención, sin dar consejos psicológicos ni legales."], "otroSector": "El mismo estudio sirve para entender la adaptación de nuevos empleados a una ciudad."}$a37sld$::jsonb,47),
('sentido-de-pertenencia-que-lo-favorece-y-por-que-algunas-persona','sociedad',array['salud']::text[],'Sentido de pertenencia: qué lo favorece y por qué algunas personas se sienten desconectadas de su comunidad','Explora qué hace que una persona sienta que pertenece a una comunidad y qué experiencias la dejan desconectada, con una encuesta anónima y lecturas, para entender cómo fortalecer vínculos.','Investigación','3 a 4 semanas',24,array['Pertenencia','Vínculos']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion diseno de encuestas. analisis cualitativo. sintesis. redaccion. un formulario en linea. hoja de calculo. fuentes confiables.',$a38sld${"id": "sentido-de-pertenencia-que-lo-favorece-y-por-que-algunas-persona", "area": "sociedad", "areas2": ["salud"], "titulo": "Sentido de pertenencia: qué lo favorece y por qué algunas personas se sienten desconectadas de su comunidad", "resumen": "Explora qué hace que una persona sienta que pertenece a una comunidad y qué experiencias la dejan desconectada, con una encuesta anónima y lecturas, para entender cómo fortalecer vínculos.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Pertenencia", "Vínculos"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Se puede vivir años en un barrio o estudiar en una universidad sin sentirse parte. La pertenencia se construye con vínculos, con reconocimiento y con espacios compartidos, y se debilita cuando faltan.", "Entender sus factores permite diseñar acciones para que más personas se sientan parte."], "desarrollar": ["Diseña una encuesta anónima que pregunte qué tan parte de la comunidad se sienten las personas, con qué cosas se asocia ese sentimiento y qué experiencias lo hicieron crecer o disminuir. Complétala con lecturas confiables sobre pertenencia.", "Agrupa los factores, como participación, trato, tradiciones compartidas y vínculos personales, y propón cinco acciones para fortalecer la pertenencia con ejemplos aplicables a un barrio o una universidad."], "ampliaciones": [{"titulo": "Primer año", "aporta": "analiza cómo cambia la pertenencia con el tiempo."}, {"titulo": "Símbolos compartidos", "aporta": "analiza el papel de símbolos y rituales."}, {"titulo": "Quienes se sienten fuera", "aporta": "estudia por qué algunas personas no se sienten parte."}], "objetivos": ["Medir sentido de pertenencia.", "Identificar factores.", "Proponer acciones.", "Redactar conclusiones."], "habilidades": ["Diseño de encuestas.", "Análisis cualitativo.", "Síntesis.", "Redacción."], "herramientas": ["Un formulario en línea.", "Hoja de cálculo.", "Fuentes confiables."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trata el tema con respeto: usa casos inventados o anónimos, sin datos que identifiquen a nadie, y si alguien necesita ayuda urgente remítelo a los servicios oficiales de atención, sin dar consejos psicológicos ni legales.", "Si una respuesta sugiere malestar emocional, remite a servicios de bienestar sin intentar dar consejos."], "otroSector": "El mismo estudio sirve para medir la pertenencia en un equipo de trabajo."}$a38sld$::jsonb,48),
('guia-de-bienvenida-para-nuevos-integrantes-de-una-comunidad-o-de','sociedad',array['educacion']::text[],'Guía de bienvenida para nuevos integrantes de una comunidad o de estudiantes que llegan de otras regiones','Elabora una guía de bienvenida para quienes llegan a una comunidad, como estudiantes que vienen de otras regiones, con información práctica, consejos de quienes ya pasaron por ello y contactos de ayuda.','Guía','3 a 4 semanas',24,array['Bienvenida','Integración']::text[],array['crear']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion sintesis. redaccion cercana. diseno de guias. empatia. un editor de documentos. un editor de mapas. un formulario de opinion.',$a39sld${"id": "guia-de-bienvenida-para-nuevos-integrantes-de-una-comunidad-o-de", "area": "sociedad", "areas2": ["educacion"], "titulo": "Guía de bienvenida para nuevos integrantes de una comunidad o de estudiantes que llegan de otras regiones", "resumen": "Elabora una guía de bienvenida para quienes llegan a una comunidad, como estudiantes que vienen de otras regiones, con información práctica, consejos de quienes ya pasaron por ello y contactos de ayuda.", "tipo": "Guía", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Bienvenida", "Integración"], "intencion": ["crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Quien llega de otra región suele enfrentar muchas dudas a la vez: dónde vivir, cómo moverse, qué trámites hacer, dónde comer barato y cómo conocer gente. La información circula informalmente y no todos la tienen.", "Una guía de bienvenida ordenada puede ahorrar tiempo y angustia."], "desarrollar": ["Con tu experiencia y la de cinco a diez compañeros que llegaron de otras regiones, reúne qué les habría ayudado saber: costos, zonas, transporte, trámites, lugares de comida, redes de apoyo y costumbres locales. Organiza todo por etapas: antes de llegar, primera semana y primer mes.", "Redacta la guía en lenguaje cercano, incluye un mapa simple y contactos de servicios oficiales, y pruébala con alguien recién llegado para ver qué faltó."], "ampliaciones": [{"titulo": "Versión corta", "aporta": "crea una tarjeta de bolsillo con lo esencial."}, {"titulo": "Voces de la comunidad", "aporta": "agrega testimonios anónimos de estudiantes."}, {"titulo": "Padrinos y madrinas", "aporta": "propón un sistema de acompañamiento entre estudiantes."}], "objetivos": ["Recoger consejos de quienes llegaron.", "Organizar por etapas.", "Redactar una guía clara.", "Probarla con un recién llegado."], "habilidades": ["Síntesis.", "Redacción cercana.", "Diseño de guías.", "Empatía."], "herramientas": ["Un editor de documentos.", "Un editor de mapas.", "Un formulario de opinión."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "No incluyas datos de contacto personales: usa servicios oficiales y verifica los datos antes de publicarlos."], "otroSector": "La misma guía sirve para dar la bienvenida a nuevos empleados o a personas que migran por trabajo."}$a39sld$::jsonb,49),
('redes-de-apoyo-para-personas-recien-llegadas-y-como-pueden-las-c','sociedad',array['educacion']::text[],'Redes de apoyo para personas recién llegadas y cómo pueden las comunidades facilitar su integración','Diseña una red de apoyo para personas recién llegadas a una comunidad, con acompañamiento entre vecinos o estudiantes, actividades de bienvenida y formas de que la comunidad facilite la integración.','Plan','3 a 4 semanas',24,array['Redes de apoyo','Integración']::text[],array['crear','investigar']::text[],'ficticios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion diseno de programas. planificacion. empatia. redaccion. un editor de documentos. un editor de diagramas. formularios simples.',$a40sld${"id": "redes-de-apoyo-para-personas-recien-llegadas-y-como-pueden-las-c", "area": "sociedad", "areas2": ["educacion"], "titulo": "Redes de apoyo para personas recién llegadas y cómo pueden las comunidades facilitar su integración", "resumen": "Diseña una red de apoyo para personas recién llegadas a una comunidad, con acompañamiento entre vecinos o estudiantes, actividades de bienvenida y formas de que la comunidad facilite la integración.", "tipo": "Plan", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Redes de apoyo", "Integración"], "intencion": ["crear", "investigar"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Las personas recién llegadas necesitan información y compañía, pero muchas comunidades no tienen una forma organizada de ofrecerlas. Quien llega se queda con el grupo que encuentra por casualidad, o con ninguno.", "Una red de apoyo sencilla puede cambiar mucho la experiencia de llegada."], "desarrollar": ["Con experiencias de integración documentadas, diseña una red de apoyo con acompañantes voluntarios, actividades de bienvenida, una persona de contacto y un calendario de encuentros durante el primer mes. Define reglas de respeto y límites.", "Prueba el diseño con casos ficticios, anticipa riesgos, como dependencia o exceso de carga a los acompañantes, y redacta una propuesta de dos páginas para presentarla a una asociación o institución."], "ampliaciones": [{"titulo": "Actividades de integración", "aporta": "diseña dos o tres actividades de bienvenida."}, {"titulo": "Formación de acompañantes", "aporta": "prepara una breve orientación para voluntarios."}, {"titulo": "Evaluación", "aporta": "define cómo saber si la red ayuda."}], "objetivos": ["Diseñar una red de apoyo.", "Definir roles y reglas.", "Anticipar riesgos.", "Redactar la propuesta."], "habilidades": ["Diseño de programas.", "Planificación.", "Empatía.", "Redacción."], "herramientas": ["Un editor de documentos.", "Un editor de diagramas.", "Formularios simples."], "lineamientos": ["Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Preséntala como propuesta: no la ejecutes sin acuerdo de la institución o de la comunidad."], "otroSector": "El mismo diseño sirve para programas de acogida de nuevos empleados o de personas migrantes."}$a40sld$::jsonb,50),
('que-ayuda-a-una-persona-a-integrarse-mejor-y-que-tan-facil-es-in','sociedad',array['educacion']::text[],'¿Qué ayuda a una persona a integrarse mejor y qué tan fácil es integrarse a una comunidad universitaria?','Descubre qué factores facilitan o dificultan que una persona nueva se integre a la comunidad universitaria, con una encuesta anónima a ingresantes y estudiantes de ciclos avanzados.','Investigación','3 a 4 semanas',24,array['Integración','Comunidad universitaria']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion diseno de encuestas. analisis de datos. entrevistas. redaccion. un formulario en linea. hoja de calculo. una guia de conversacion.',$a41sld${"id": "que-ayuda-a-una-persona-a-integrarse-mejor-y-que-tan-facil-es-in", "area": "sociedad", "areas2": ["educacion"], "titulo": "¿Qué ayuda a una persona a integrarse mejor y qué tan fácil es integrarse a una comunidad universitaria?", "resumen": "Descubre qué factores facilitan o dificultan que una persona nueva se integre a la comunidad universitaria, con una encuesta anónima a ingresantes y estudiantes de ciclos avanzados.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Integración", "Comunidad universitaria"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Entrar a la universidad implica hacer nuevos amigos, entender códigos y encontrar un lugar. Algunos lo logran rápido y otros pasan semanas sin sentirse parte. Las diferencias dependen de redes, de actividades y del trato recibido.", "Saber qué ayuda permite diseñar acciones de integración que funcionen."], "desarrollar": ["Con una encuesta anónima de diez preguntas a 30 o más estudiantes, pregunta qué tan fácil les resultó integrarse, qué los ayudó, qué los frenó y qué actividad o persona fue clave. Complementa con tres a cinco conversaciones voluntarias.", "Compara respuestas por ciclo y por situación, como estudiantes que viven lejos o que trabajan, y resume los factores que más se repiten. Propón cinco acciones concretas de integración para ingresantes."], "ampliaciones": [{"titulo": "Primer mes", "aporta": "analiza qué ocurre en las primeras cuatro semanas."}, {"titulo": "Clubes y actividades", "aporta": "estudia el papel de clubes y talleres."}, {"titulo": "Padrinos de ingresantes", "aporta": "diseña un programa de acompañamiento entre estudiantes."}], "objetivos": ["Medir facilidad de integración.", "Identificar factores clave.", "Comparar por grupos.", "Proponer acciones."], "habilidades": ["Diseño de encuestas.", "Análisis de datos.", "Entrevistas.", "Redacción."], "herramientas": ["Un formulario en línea.", "Hoja de cálculo.", "Una guía de conversación."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir."], "otroSector": "El mismo estudio sirve para entender la integración de nuevos empleados a una organización."}$a41sld$::jsonb,51),
('tradiciones-que-fortalecen-la-identidad-de-una-comunidad-y-el-va','sociedad',array['arte']::text[],'Tradiciones que fortalecen la identidad de una comunidad y el valor de las costumbres locales','Reúne las tradiciones y costumbres que dan identidad a una comunidad y explica qué significan para quienes las practican, cómo se viven y qué función cumplen en la vida colectiva.','Investigación','3 a 4 semanas',24,array['Tradiciones','Identidad']::text[],array['investigar','crear']::text[],'propios',NULL,'sociologia antropologia trabajo social educacion comunicaciones psicologia diseno historia entrevistas. registro etnografico basico. sintesis. redaccion. una guia de conversacion. un editor de documentos. camara o grabadora con permiso.',$a42sld${"id": "tradiciones-que-fortalecen-la-identidad-de-una-comunidad-y-el-va", "area": "sociedad", "areas2": ["arte"], "titulo": "Tradiciones que fortalecen la identidad de una comunidad y el valor de las costumbres locales", "resumen": "Reúne las tradiciones y costumbres que dan identidad a una comunidad y explica qué significan para quienes las practican, cómo se viven y qué función cumplen en la vida colectiva.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Tradiciones", "Identidad"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Sociología", "Antropología", "Trabajo Social", "Educación", "Comunicaciones", "Psicología", "Diseño", "Historia"], "problema": ["Fiestas, comidas, músicas, saludos y formas de celebrar ayudan a que una comunidad se reconozca a sí misma. A menudo se ven como algo folclórico, pero cumplen funciones como cohesión, memoria y orgullo compartido.", "Documentar su significado ayuda a valorarlas y a transmitirlas."], "desarrollar": ["Elige una comunidad y, con permiso, conversa con personas de distintas edades sobre las tradiciones que consideran importantes, qué significan para ellas y cuándo y cómo se practican. Registra con respeto, sin grabar si no lo permiten.", "Organiza la información en fichas por tradición, con descripción, significado, quiénes participan y cambios en el tiempo, y analiza qué funciones cumplen en la vida comunitaria."], "ampliaciones": [{"titulo": "Calendario de tradiciones", "aporta": "arma un calendario anual con las celebraciones."}, {"titulo": "Voces de varias generaciones", "aporta": "compara lo que cada generación valora."}, {"titulo": "Material para compartir", "aporta": "convierte las fichas en una publicación breve."}], "objetivos": ["Recoger tradiciones locales.", "Describir su significado.", "Organizar fichas.", "Analizar su función comunitaria."], "habilidades": ["Entrevistas.", "Registro etnográfico básico.", "Síntesis.", "Redacción."], "herramientas": ["Una guía de conversación.", "Un editor de documentos.", "Cámara o grabadora con permiso."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "No registres rituales o conocimientos sagrados sin autorización expresa de la comunidad."], "otroSector": "El mismo trabajo sirve para documentar la cultura organizacional de una empresa."}$a42sld$::jsonb,52),
('documentando-manifestaciones-culturales-de-una-comunidad-un-regi','sociedad',array['arte']::text[],'Documentando manifestaciones culturales de una comunidad: un registro de costumbres y tradiciones','Crea un registro ordenado de costumbres, fiestas, platos, música y oficios de una comunidad, con fichas, fotos o dibujos y testimonios, pensado para conservar la memoria local.','Prototipo','4 a 5 semanas',28,array['Patrimonio cultural','Registro']::text[],array['crear','investigar']::text[],'propios',NULL,'sociologia antropologia trabajo social educacion comunicaciones psicologia diseno historia registro etnografico basico. entrevistas. diseno de fichas. edicion de materiales. una ficha de registro. un editor de documentos. camara o grabadora con permiso.',$a43sld${"id": "documentando-manifestaciones-culturales-de-una-comunidad-un-regi", "area": "sociedad", "areas2": ["arte"], "titulo": "Documentando manifestaciones culturales de una comunidad: un registro de costumbres y tradiciones", "resumen": "Crea un registro ordenado de costumbres, fiestas, platos, música y oficios de una comunidad, con fichas, fotos o dibujos y testimonios, pensado para conservar la memoria local.", "tipo": "Prototipo", "tiempo": "4 a 5 semanas", "horas": 28, "etiquetas": ["Patrimonio cultural", "Registro"], "intencion": ["crear", "investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Sociología", "Antropología", "Trabajo Social", "Educación", "Comunicaciones", "Psicología", "Diseño", "Historia"], "problema": ["Muchas costumbres de las comunidades se transmiten oralmente y se pierden cuando cambian las generaciones. Pocas veces se documentan con orden y con el permiso de quienes las portan.", "Un registro cuidadoso permite conservarlas y compartirlas con respeto."], "desarrollar": ["Define el alcance, como una fiesta o diez costumbres, y diseña una ficha de registro con nombre, descripción, época, quiénes participan, significado y cómo se transmite. Aplícala con personas de la comunidad que quieran compartir su conocimiento.", "Organiza las fichas en un archivo digital o impreso, valida con los participantes que su contenido es correcto y pide su permiso para compartirlo. Entrega el registro con una portada y un índice."], "ampliaciones": [{"titulo": "Mapa cultural", "aporta": "ubica las manifestaciones en un mapa de la zona."}, {"titulo": "Archivo oral", "aporta": "agrega testimonios con permiso."}, {"titulo": "Devolución a la comunidad", "aporta": "organiza una pequeña muestra de lo registrado."}], "objetivos": ["Diseñar una ficha de registro.", "Recoger información con permiso.", "Validar con la comunidad.", "Entregar un registro organizado."], "habilidades": ["Registro etnográfico básico.", "Entrevistas.", "Diseño de fichas.", "Edición de materiales."], "herramientas": ["Una ficha de registro.", "Un editor de documentos.", "Cámara o grabadora con permiso."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Pide permiso expreso para fotos, voces y conocimientos, y devuelve el registro a la comunidad."], "otroSector": "El mismo registro sirve para conservar la memoria de una empresa o de una institución."}$a43sld$::jsonb,53),
('como-cambian-las-tradiciones-con-el-tiempo-y-entre-generaciones','sociedad',array['arte']::text[],'¿Cómo cambian las tradiciones con el tiempo y entre generaciones de una familia?','Compara cómo se vivía una tradición hace décadas y cómo se vive hoy, a través de conversaciones con personas de distintas edades, y analiza qué cambió y qué se mantiene.','Investigación','3 a 4 semanas',22,array['Cambio cultural','Generaciones']::text[],array['investigar']::text[],'propios',NULL,'sociologia antropologia trabajo social educacion comunicaciones psicologia diseno historia entrevistas. analisis comparativo. sintesis. redaccion. una guia de conversacion. un editor de lineas de tiempo. un editor de documentos.',$a44sld${"id": "como-cambian-las-tradiciones-con-el-tiempo-y-entre-generaciones", "area": "sociedad", "areas2": ["arte"], "titulo": "¿Cómo cambian las tradiciones con el tiempo y entre generaciones de una familia?", "resumen": "Compara cómo se vivía una tradición hace décadas y cómo se vive hoy, a través de conversaciones con personas de distintas edades, y analiza qué cambió y qué se mantiene.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Cambio cultural", "Generaciones"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Sociología", "Antropología", "Trabajo Social", "Educación", "Comunicaciones", "Psicología", "Diseño", "Historia"], "problema": ["Las tradiciones no son fijas: cambian con la migración, la tecnología, la economía y los gustos. A veces se ven esos cambios como pérdidas, pero otras veces son adaptaciones que mantienen vivas las costumbres.", "Analizar cómo cambian ayuda a entender qué se transmite y qué no."], "desarrollar": ["Elige una tradición o costumbre familiar o comunitaria y conversa, con permiso, con personas de tres generaciones sobre cómo la recuerdan o viven. Registra qué elementos se mantienen, cuáles cambiaron y por qué.", "Dibuja una línea de tiempo del cambio, compara las versiones y escribe una reflexión sobre qué factores influyeron, evitando juzgar si el cambio es bueno o malo."], "ampliaciones": [{"titulo": "Lo que se perdió", "aporta": "identifica elementos que ya no se practican y por qué."}, {"titulo": "Lo que se inventó", "aporta": "analiza costumbres nuevas que se volvieron tradición."}, {"titulo": "Fotografías antiguas", "aporta": "usa fotos familiares con permiso para ilustrar."}], "objetivos": ["Recoger versiones de varias generaciones.", "Comparar cambios y continuidades.", "Analizar factores.", "Presentar una reflexión."], "habilidades": ["Entrevistas.", "Análisis comparativo.", "Síntesis.", "Redacción."], "herramientas": ["Una guía de conversación.", "Un editor de líneas de tiempo.", "Un editor de documentos."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Pide permiso para citar o mostrar las historias de familiares."], "otroSector": "El mismo análisis sirve para estudiar el cambio de prácticas en una organización a lo largo de los años."}$a44sld$::jsonb,54),
('analizando-la-transmision-de-conocimientos-entre-generaciones','sociedad',array['educacion']::text[],'Analizando la transmisión de conocimientos entre generaciones','Analiza cómo se transmiten los conocimientos tradicionales, como recetas, oficios o remedios caseros, de una generación a otra, y qué ocurre cuando esa transmisión se interrumpe.','Investigación','3 semanas',22,array['Saberes','Transmisión']::text[],array['investigar']::text[],'propios',NULL,'sociologia antropologia trabajo social educacion comunicaciones psicologia diseno historia entrevistas. analisis cualitativo. sintesis. redaccion. una guia de conversacion. un editor de documentos. camara o grabadora con permiso.',$a45sld${"id": "analizando-la-transmision-de-conocimientos-entre-generaciones", "area": "sociedad", "areas2": ["educacion"], "titulo": "Analizando la transmisión de conocimientos entre generaciones", "resumen": "Analiza cómo se transmiten los conocimientos tradicionales, como recetas, oficios o remedios caseros, de una generación a otra, y qué ocurre cuando esa transmisión se interrumpe.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Saberes", "Transmisión"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Sociología", "Antropología", "Trabajo Social", "Educación", "Comunicaciones", "Psicología", "Diseño", "Historia"], "problema": ["Muchas habilidades y saberes no están escritos: se aprenden mirando, ayudando y conversando con alguien mayor. Con la migración, el trabajo y los cambios de vida, esa cadena de transmisión se debilita y los saberes pueden perderse.", "Entender cómo se transmiten permite pensar cómo conservarlos."], "desarrollar": ["Elige tres saberes, como una receta, un oficio o una técnica, y conversa con quien los domina y con quien los aprendió, para describir cómo se transmitió, cuánto tiempo tomó y qué condiciones lo facilitaron.", "Analiza qué obstáculos impiden hoy que más personas aprendan estos saberes y propón formas de seguir transmitiéndolos, como talleres, registros o encuentros entre generaciones."], "ampliaciones": [{"titulo": "Quién enseña", "aporta": "identifica los roles de abuelos, padres o maestros."}, {"titulo": "Aprender mirando", "aporta": "analiza formas de aprendizaje no formales."}, {"titulo": "Registro respetuoso", "aporta": "propón cómo registrar un saber sin banalizarlo."}], "objetivos": ["Describir cómo se transmite un saber.", "Identificar condiciones y obstáculos.", "Proponer formas de conservar.", "Presentar el análisis."], "habilidades": ["Entrevistas.", "Análisis cualitativo.", "Síntesis.", "Redacción."], "herramientas": ["Una guía de conversación.", "Un editor de documentos.", "Cámara o grabadora con permiso."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Respeta que algunos saberes pertenecen a una familia o comunidad y no deben difundirse sin su acuerdo."], "otroSector": "El mismo análisis sirve para la transferencia de conocimiento tácito en una empresa."}$a45sld$::jsonb,55),
('fortaleciendo-los-vinculos-entre-generaciones-propuesta-de-espac','sociedad',array['educacion']::text[],'Fortaleciendo los vínculos entre generaciones: propuesta de espacios de encuentro y colaboración','Diseña una propuesta de actividades que reúnan a personas de distintas edades, como talleres de oficios, cuentacuentos o apoyo escolar, y analiza qué sucede cuando desaparecen los espacios de encuentro.','Plan','4 semanas',26,array['Intergeneracional','Espacios de encuentro']::text[],array['crear']::text[],'ficticios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion diseno de programas. planificacion. empatia. redaccion. un editor de documentos. hoja de calculo. un editor de presentaciones.',$a46sld${"id": "fortaleciendo-los-vinculos-entre-generaciones-propuesta-de-espac", "area": "sociedad", "areas2": ["educacion"], "titulo": "Fortaleciendo los vínculos entre generaciones: propuesta de espacios de encuentro y colaboración", "resumen": "Diseña una propuesta de actividades que reúnan a personas de distintas edades, como talleres de oficios, cuentacuentos o apoyo escolar, y analiza qué sucede cuando desaparecen los espacios de encuentro.", "tipo": "Plan", "tiempo": "4 semanas", "horas": 26, "etiquetas": ["Intergeneracional", "Espacios de encuentro"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Cada vez hay menos espacios donde jóvenes, adultos y personas mayores compartan tiempo: se separan por escuelas, trabajos y pantallas. Eso debilita la transmisión de saberes y la comprensión mutua.", "Diseñar espacios de encuentro puede reconstruir esos vínculos."], "desarrollar": ["Con experiencias documentadas de programas intergeneracionales, diseña tres actividades para tu comunidad, como un taller donde mayores enseñan un oficio y jóvenes enseñan tecnología. Define objetivos, materiales, duración y cómo cuidar el trato respetuoso.", "Analiza qué factores hacen que estos espacios funcionen, como horarios, lugares accesibles y propósito compartido, y presenta la propuesta en un documento de dos a tres páginas con un plan de evaluación."], "ampliaciones": [{"titulo": "Diagnóstico de espacios", "aporta": "identifica qué espacios de encuentro existen y cuáles se perdieron."}, {"titulo": "Presupuesto", "aporta": "estima costos y cómo cubrirlos."}, {"titulo": "Prueba piloto", "aporta": "propón cómo ensayar una actividad."}], "objetivos": ["Diseñar actividades intergeneracionales.", "Identificar condiciones de éxito.", "Plantear una evaluación.", "Redactar la propuesta."], "habilidades": ["Diseño de programas.", "Planificación.", "Empatía.", "Redacción."], "herramientas": ["Un editor de documentos.", "Hoja de cálculo.", "Un editor de presentaciones."], "lineamientos": ["Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Preséntala como propuesta y no organices actividades con menores sin autorización y acompañamiento adulto."], "otroSector": "El mismo diseño sirve para programas de mentoría entre trabajadores jóvenes y veteranos."}$a46sld$::jsonb,56),
('que-tradiciones-locales-estan-dejando-de-practicarse-entre-las-n','sociedad',array['arte']::text[],'¿Qué tradiciones locales están dejando de practicarse entre las nuevas generaciones?','Averigua qué tradiciones locales practican cada vez menos los jóvenes y por qué, con una encuesta anónima y conversaciones, sin juzgar y distinguiendo entre pérdida y cambio.','Investigación','3 semanas',20,array['Tradiciones en riesgo','Nuevas generaciones']::text[],array['investigar']::text[],'propios',NULL,'sociologia antropologia trabajo social educacion comunicaciones psicologia diseno historia diseno de encuestas. analisis de datos. entrevistas. redaccion. un formulario en linea. hoja de calculo. una guia de conversacion.',$a47sld${"id": "que-tradiciones-locales-estan-dejando-de-practicarse-entre-las-n", "area": "sociedad", "areas2": ["arte"], "titulo": "¿Qué tradiciones locales están dejando de practicarse entre las nuevas generaciones?", "resumen": "Averigua qué tradiciones locales practican cada vez menos los jóvenes y por qué, con una encuesta anónima y conversaciones, sin juzgar y distinguiendo entre pérdida y cambio.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Tradiciones en riesgo", "Nuevas generaciones"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Sociología", "Antropología", "Trabajo Social", "Educación", "Comunicaciones", "Psicología", "Diseño", "Historia"], "problema": ["Se dice que los jóvenes ya no valoran sus tradiciones, pero pocas veces se les pregunta. A veces dejan de practicarlas por falta de tiempo, por cambios en la vida diaria, por migración o porque nadie les enseñó.", "Conocer los motivos permite no culparlos y pensar cómo mantener lo que desean conservar."], "desarrollar": ["Diseña una encuesta anónima para jóvenes y adultos con una lista de tradiciones locales, pregunta cuáles practican, cuáles conocen y cuáles dejaron de hacer, y por qué. Complementa con tres a cinco conversaciones voluntarias.", "Compara las respuestas por edad, identifica las tradiciones con mayor riesgo de desaparecer y los motivos, y propón ideas para mantenerlas, como talleres, registros o nuevas formas de vivirlas."], "ampliaciones": [{"titulo": "Rescate participativo", "aporta": "diseña una actividad para recuperar una tradición."}, {"titulo": "Quién la mantiene", "aporta": "identifica a las personas que sostienen cada tradición."}, {"titulo": "Nuevas versiones", "aporta": "documenta cómo los jóvenes reinventan tradiciones."}], "objetivos": ["Diseñar una encuesta anónima.", "Identificar tradiciones en riesgo.", "Analizar motivos.", "Proponer ideas."], "habilidades": ["Diseño de encuestas.", "Análisis de datos.", "Entrevistas.", "Redacción."], "herramientas": ["Un formulario en línea.", "Hoja de cálculo.", "Una guía de conversación."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir."], "otroSector": "El mismo estudio sirve para entender qué prácticas de una organización dejan de usarse."}$a47sld$::jsonb,57),
('que-papel-cumplen-las-actividades-culturales-en-la-integracion-d','sociedad',array['arte']::text[],'¿Qué papel cumplen las actividades culturales en la integración de una comunidad?','Analiza cómo festivales, ferias, talleres y celebraciones ayudan a que personas distintas se conozcan y se integren, y qué características hacen que una actividad cultural sea realmente inclusiva.','Análisis','3 semanas',22,array['Actividades culturales','Integración']::text[],array['investigar']::text[],'publicos',NULL,'sociologia antropologia trabajo social educacion comunicaciones psicologia diseno historia observacion. analisis cualitativo. pensamiento critico. redaccion. informacion publica. una guia de observacion. un editor de documentos.',$a48sld${"id": "que-papel-cumplen-las-actividades-culturales-en-la-integracion-d", "area": "sociedad", "areas2": ["arte"], "titulo": "¿Qué papel cumplen las actividades culturales en la integración de una comunidad?", "resumen": "Analiza cómo festivales, ferias, talleres y celebraciones ayudan a que personas distintas se conozcan y se integren, y qué características hacen que una actividad cultural sea realmente inclusiva.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Actividades culturales", "Integración"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Sociología", "Antropología", "Trabajo Social", "Educación", "Comunicaciones", "Psicología", "Diseño", "Historia"], "problema": ["Una fiesta, una feria o un festival pueden juntar a personas que de otra forma no se encontrarían. Pero no todas las actividades culturales integran: algunas se vuelven espacios cerrados o poco accesibles.", "Entender qué las hace integradoras permite diseñarlas mejor."], "desarrollar": ["Con información pública y observación respetuosa, describe tres actividades culturales de tu zona y analiza quiénes participan, quiénes no, qué barreras hay y qué efectos dicen tener en la convivencia.", "Elabora una lista de características que favorecen la integración, como acceso gratuito, participación de varios grupos y horarios amplios, y aplícala a una actividad de ejemplo con propuestas de mejora."], "ampliaciones": [{"titulo": "Impacto en vínculos", "aporta": "pregunta a participantes con quién se conocieron en la actividad."}, {"titulo": "Presupuesto cultural", "aporta": "analiza cuánto cuesta organizarla y quién paga."}, {"titulo": "Actividades virtuales", "aporta": "compara con espacios culturales en línea."}], "objetivos": ["Describir actividades culturales.", "Analizar quién participa y quién no.", "Elaborar criterios de integración.", "Proponer mejoras."], "habilidades": ["Observación.", "Análisis cualitativo.", "Pensamiento crítico.", "Redacción."], "herramientas": ["Información pública.", "Una guía de observación.", "Un editor de documentos."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Pide permiso a los organizadores antes de observar o escribir sobre su actividad."], "otroSector": "El mismo análisis sirve para evaluar eventos corporativos o de integración."}$a48sld$::jsonb,58)
